svg.script:
(function() {
  'use strict';

  // Data Store for 7 Nominal Vulvar Structures
  var structuresData = {
    'caruncula-himenal': {
      title: 'Carúncula Himenal',
      badgeText: 'PONTO ZERO',
      badgeBg: 'var(--a12p21-caruncula)',
      badgeColor: '#181316',
      position: 'Medial-Posterior / Marco Zero (0 cm)',
      desc: 'Remanescentes nodulares mirtiformes da membrana himenal após sua rotura. Ficam localizados na circunferência do intróito vaginal e delimitam o vestíbulo vulvar da vagina.',
      popqTitle: 'APLICAÇÃO CLÍNICA: ESTADIAMENTO POP-Q',
      popqContent: '<p style="margin:0 0 6px 0;"><strong>Marco Zero (0 cm):</strong> No sistema POP-Q (Pelvic Organ Prolapse Quantification), o plano do hímen representa o plano de referência zero absoluto.</p><p style="margin:0 0 6px 0;"><span style="color:var(--a12p21-orientacao); font-weight:700;">Valores Negativos (- cm):</span> Estruturas prolapsadas acima do hímen (intravaginais).</p><p style="margin:0;"><span style="color:var(--a12p21-foco); font-weight:700;">Valores Positivos (+ cm):</span> Estruturas projetadas distalmente além do hímen.</p>',
      rose: { ant: false, post: true, med: true, lat: false },
      leaderY: 260
    },
    'monte-pubico': {
      title: 'Monte Púbico',
      badgeText: 'ANTERIOR',
      badgeBg: 'var(--a12p21-tecido)',
      badgeColor: '#FFFFFF',
      position: 'Anterior / Superficial',
      desc: 'Proeminência adiposa arredondada situada anterior e superiormente à sínfise púbica. Revestida por pele e pelos pubianos (glandas sebáceas e sudoríparas).',
      popqTitle: 'RELEVÂNCIA ANATÔMICA',
      popqContent: '<p style="margin:0 0 6px 0;"><strong>Limite Vulvar Superior:</strong> Atua como coxim protetor anterior sobre a arcada óssea púbica.</p><p style="margin:0;">Fora do eixo direto da régua de estadiamento POP-Q, porém delimita o ápice anatômico da genitália externa.</p>',
      rose: { ant: true, post: false, med: false, lat: false },
      leaderY: 100
    },
    'clitoris': {
      title: 'Clitóris e Prepúcio',
      badgeText: 'ANT-MEDIAL',
      badgeBg: 'var(--a12p21-foco)',
      badgeColor: '#FFFFFF',
      position: 'Anterior-Medial / Apical',
      desc: 'Órgão erétil homólogo ao pênis. Formado por glande visível, prepúcio (fusão superior dos pequenos lábios), frênulo, corpo e cruras internas.',
      popqTitle: 'ORIENTAÇÃO CLÍNICA',
      popqContent: '<p style="margin:0 0 6px 0;"><strong>Marco Erétil Apical:</strong> Situado no encontro anterior das pregas labiais.</p><p style="margin:0;"><span style="color:var(--a12p21-foco); font-weight:700;">Vascularização & Inervação:</span> Altamente irrigado pelo ramo terminal da artéria pudenda interna e nervo dorsal do clitóris.</p>',
      rose: { ant: true, post: false, med: true, lat: false },
      leaderY: 130
    },
    'ostio-uretral': {
      title: 'Óstio Uretral Externo',
      badgeText: 'MEDIAL',
      badgeBg: 'var(--a12p21-orientacao)',
      badgeColor: '#FFFFFF',
      position: 'Medial-Anterior (Vestíbulo)',
      desc: 'Abertura externa da uretra situada na linha média do vestíbulo vaginal, aproximadamente 2 a 2.5 cm inferior à glande do clitóris e anterior ao intróito.',
      popqTitle: 'RELEVÂNCIA NO POP-Q (MEDIDA GH/PB)',
      popqContent: '<p style="margin:0 0 6px 0;"><strong>Marco do Hiato Genital (gh):</strong> A distância do meato uretral externo até a comissura posterior do hímen define a medida do hiato genital (gh).</p><p style="margin:0;">Essencial na avaliação de hipertrofia do hiato e rotura perineal.</p>',
      rose: { ant: true, post: false, med: true, lat: false },
      leaderY: 175
    },
    'pequenos-labios': {
      title: 'Pequenos Lábios',
      badgeText: 'MED-LATERAL',
      badgeBg: 'var(--a12p21-tecido)',
      badgeColor: '#FFFFFF',
      position: 'Medial-Lateral (Ninfas)',
      desc: 'Duas dobras cutâneo-mucosas desprovidas de tecido adiposo e pelos. Delimitam lateralmente o vestíbulo vaginal e bifurcam-se na extremidade anterior para formar o prepúcio e o frênulo do clitóris.',
      popqTitle: 'FUNÇÃO PROTECTORA',
      popqContent: '<p style="margin:0 0 6px 0;"><strong>Proteção Vestibular:</strong> Recobrem e protegem o óstio uretral externo e o intróito vaginal.</p><p style="margin:0;">Apresentam rica inervação sensitiva e vascularização erétil secundária.</p>',
      rose: { ant: false, post: false, med: true, lat: true },
      leaderY: 220
    },
    'grandes-labios': {
      title: 'Grandes Lábios',
      badgeText: 'LATERAL',
      badgeBg: 'var(--a12p21-tecido)',
      badgeColor: '#FFFFFF',
      position: 'Lateral (Limites Vulvares)',
      desc: 'Duas pregas cutâneas longitudinais salientes contendo tecido adiposo, músculo liso (dartos vulvar) e glândulas sebáceas/sudoríparas. Estendem-se do monte púbico até o corpo perineal.',
      popqTitle: 'DELIMITAÇÃO ANATÔMICA',
      popqContent: '<p style="margin:0 0 6px 0;"><strong>Fenda Vulvar:</strong> Encerram a fenda vulvar lateralmente.</p><p style="margin:0;">Homólogos ao escroto masculino. Unem-se na comissura anterior e na comissura posterior da vulva.</p>',
      rose: { ant: false, post: true, med: false, lat: true },
      leaderY: 240
    },
    'introito-vaginal': {
      title: 'Intróito Vaginal',
      badgeText: 'POST-MEDIAL',
      badgeBg: 'var(--a12p21-contorno)',
      badgeColor: '#FFFFFF',
      position: 'Medial-Posterior / Óstio Vagina',
      desc: 'Abertura inferior da vagina no vestíbulo vulvar. Limite anatômico de transição entre a genitália externa e o canal vaginal interno.',
      popqTitle: 'EIXO DOS PROLAPSOS (POP-Q)',
      popqContent: '<p style="margin:0 0 6px 0;"><strong>Abertura de Egressão:</strong> Orifício por onde exteriorizam-se as distopias pélvicas (Cistocele, Rectocele e Prolapso Uterino/Cúpula).</p><p style="margin:0;">O hímen / carúncula delimita a margem exata desta abertura.</p>',
      rose: { ant: false, post: true, med: true, lat: false },
      leaderY: 260
    }
  };

  function updateScene(targetId) {
    var root = document.getElementById('a12p21-floor-root');
    if (!root || !structuresData[targetId]) return;

    // 1. Set Active Attribute on Root
    root.setAttribute('data-active-target', targetId);

    var data = structuresData[targetId];

    // 2. Update Header Info
    var badgeBg = document.getElementById('a12p21-info-badge-bg');
    var badgeText = document.getElementById('a12p21-info-badge-text');
    var titleText = document.getElementById('a12p21-info-title');
    var posText = document.getElementById('a12p21-info-position');
    var descText = document.getElementById('a12p21-info-desc-text');
    var popqTitle = document.getElementById('a12p21-popq-card-title');
    var popqContent = document.getElementById('a12p21-info-popq-content');
    var popqBorder = document.getElementById('a12p21-popq-card-border');

    if (badgeBg) badgeBg.style.fill = data.badgeBg;
    if (badgeText) {
      badgeText.textContent = data.badgeText;
      badgeText.style.fill = data.badgeColor;
    }
    if (titleText) titleText.textContent = data.title;
    if (posText) posText.textContent = data.position;
    if (descText) descText.textContent = data.desc;
    if (popqTitle) popqTitle.textContent = data.popqTitle;
    if (popqContent) popqContent.innerHTML = data.popqContent;

    if (popqBorder) {
      popqBorder.style.stroke = (targetId === 'caruncula-himenal') ? 'var(--a12p21-caruncula)' : 'var(--a12p21-panel-border)';
    }

    // 3. Update Spatial Rose Arrows & Labels
    var roseKeys = ['ant', 'post', 'med', 'lat'];
    roseKeys.forEach(function(key) {
      var arrow = document.getElementById('a12p21-rose-arrow-' + key);
      var lbl = document.getElementById('a12p21-rose-lbl-' + key);
      var isActive = data.rose[key];

      if (arrow) {
        if (isActive) arrow.classList.add('active');
        else arrow.classList.remove('active');
      }
      if (lbl) {
        if (isActive) lbl.classList.add('active');
        else lbl.classList.remove('active');
      }
    });

    // 4. Update Leader Line
    var leaderLine = document.getElementById('a12p21-leader-line');
    var leaderDot = document.getElementById('a12p21-leader-dot');
    if (leaderLine && leaderDot) {
      leaderLine.setAttribute('y1', data.leaderY);
      leaderLine.setAttribute('y2', data.leaderY);
      leaderDot.setAttribute('cy', data.leaderY);
    }
  }

  // Attach Click & Keyboard Events
  function bindEvents() {
    var targets = document.querySelectorAll('.a12p21-floor-target, .a12p21-floor-btn');
    targets.forEach(function(el) {
      var id = el.id.replace('a12p21-floor-target-', '').replace('a12p21-floor-btn-', '');

      el.addEventListener('click', function(e) {
        e.stopPropagation();
        updateScene(id);
      });

      el.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          updateScene(id);
        }
      });
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', bindEvents);
  } else {
    bindEvents();
  }
})();
